/**
 * @title Tasks table with search, filters and bulk actions
 * @description Search, status filter chips, sortable columns, row selection with a bulk-action bar that announces the count, and pagination.
 * @route /tasks
 * @height 900
 */
import { SidebarInset, SidebarProvider } from "@/components/ui/sidebar";
import { Button } from "@/components/ui/button";
import { DashboardSidebar } from "@/components/dashboard-sidebar";
import { SiteHeader } from "@/components/site-header";
import { TasksTable } from "@/components/tasks-table";

export default function Page() {
  return (
    <SidebarProvider>
      <DashboardSidebar current="Lifecycle" />
      <SidebarInset>
        <SiteHeader crumbs={[{ label: "Lifecycle", href: "#" }, { label: "Tasks" }]} />
        <div className="flex flex-1 flex-col gap-6 p-4 md:p-6">
          <div className="flex flex-wrap items-end justify-between gap-3">
            <div className="flex flex-col gap-1"><h1 className="text-heading-h2">Tasks</h1><p className="text-body-medium text-fg-secondary">Everything the team is working on this cycle.</p></div>
            <Button leadingIcon="plus">New task</Button>
          </div>
          <TasksTable />
        </div>
      </SidebarInset>
    </SidebarProvider>
  );
}

"use client";
import { BarChart3, Camera, Database, FileText, FolderKanban, Gauge, HelpCircle, LayoutDashboard, ListChecks, Search, Settings, Users } from "lucide-react";
import { Icon } from "@/components/ui/icon";
import {
  Sidebar, SidebarContent, SidebarFooter, SidebarGroup, SidebarGroupLabel, SidebarHeader, SidebarMenu, SidebarMenuButton,
  SidebarMenuItem, SidebarRail,
} from "@/components/ui/sidebar";
import { BrandHeader } from "@/components/brand-header";
import { NavSecondary } from "@/components/nav-secondary";
import { NavUser } from "@/components/nav-user";

const main = [
  { title: "Dashboard", icon: LayoutDashboard }, { title: "Lifecycle", icon: ListChecks }, { title: "Analytics", icon: BarChart3 },
  { title: "Projects", icon: FolderKanban }, { title: "Team", icon: Users },
];
const documents = [{ title: "Data library", icon: Database }, { title: "Reports", icon: FileText }, { title: "Capture", icon: Camera }];
const secondary = [{ title: "Settings", url: "#", icon: Settings }, { title: "Get help", url: "#", icon: HelpCircle }, { title: "Search", url: "#", icon: Search }];

/** The app sidebar the dashboard, settings and table blocks share. Pass the current page's title. */
export function DashboardSidebar({ current = "Dashboard", variant = "inset" }: { current?: string; variant?: "sidebar" | "inset" }) {
  return (
    <Sidebar collapsible="icon" variant={variant} label="Main navigation">
      <SidebarHeader>
        <BrandHeader name="Acme Inc" detail="Workspace" logo={Gauge} />
      </SidebarHeader>
      <SidebarContent>
        <nav aria-label="Main" className="contents">
          <SidebarGroup>
            <SidebarMenu>
              {main.map((m) => (
                <SidebarMenuItem key={m.title}>
                  <SidebarMenuButton href="#" isActive={m.title === current} tooltip={m.title}><Icon name={m.icon} /><span>{m.title}</span></SidebarMenuButton>
                </SidebarMenuItem>
              ))}
            </SidebarMenu>
          </SidebarGroup>
          <SidebarGroup>
            <SidebarGroupLabel as="h2">Documents</SidebarGroupLabel>
            <SidebarMenu>
              {documents.map((m) => (
                <SidebarMenuItem key={m.title}>
                  <SidebarMenuButton href="#" isActive={m.title === current} tooltip={m.title}><Icon name={m.icon} /><span>{m.title}</span></SidebarMenuButton>
                </SidebarMenuItem>
              ))}
            </SidebarMenu>
          </SidebarGroup>
          <NavSecondary items={secondary.map((s) => ({ ...s }))} className="mt-auto" />
        </nav>
      </SidebarContent>
      <SidebarFooter>
        <NavUser user={{ name: "Jane Cooper", email: "jane@acme.com" }} />
      </SidebarFooter>
      <SidebarRail />
    </Sidebar>
  );
}

"use client";
import { GalleryVerticalEnd, type LucideIcon } from "lucide-react";
import { Icon } from "@/components/ui/icon";
import { SidebarMenu, SidebarMenuButton, SidebarMenuItem } from "@/components/ui/sidebar";

/** Logo, product name and a second line (plan or version) at the top of the sidebar. Links home. */
export function BrandHeader({ name = "Acme Docs", detail = "v4.0.0", logo = GalleryVerticalEnd }: { name?: string; detail?: string; logo?: LucideIcon }) {
  return (
    <SidebarMenu>
      <SidebarMenuItem>
        <SidebarMenuButton href="#" size="lg" tooltip={name}>
          <span className="grid size-8 shrink-0 place-items-center rounded-control bg-brand text-fg-on-brand"><Icon name={logo} size={16} /></span>
          <span className="flex min-w-0 flex-1 flex-col">
            <span className="truncate text-label-medium text-fg-primary">{name}</span>
            <span className="truncate text-caption-default">{detail}</span>
          </span>
        </SidebarMenuButton>
      </SidebarMenuItem>
    </SidebarMenu>
  );
}

"use client";
import type { LucideIcon } from "lucide-react";
import type { HTMLAttributes } from "react";
import { Icon } from "@/components/ui/icon";
import { SidebarGroup, SidebarGroupContent, SidebarMenu, SidebarMenuButton, SidebarMenuItem } from "@/components/ui/sidebar";

/** Small links near the bottom of the sidebar (support, feedback). */
export function NavSecondary({ items, ...rest }: HTMLAttributes<HTMLDivElement> & { items: { title: string; url: string; icon: LucideIcon }[] }) {
  return (
    <SidebarGroup {...rest}>
      <SidebarGroupContent>
        <SidebarMenu>
          {items.map((item) => (
            <SidebarMenuItem key={item.title}>
              <SidebarMenuButton href={item.url} size="sm" tooltip={item.title}>
                <Icon name={item.icon} size={16} />
                <span>{item.title}</span>
              </SidebarMenuButton>
            </SidebarMenuItem>
          ))}
        </SidebarMenu>
      </SidebarGroupContent>
    </SidebarGroup>
  );
}

"use client";
import { ChevronsUpDown } from "lucide-react";
import { Avatar } from "@/components/ui/display";
import { Icon } from "@/components/ui/icon";
import { Menu } from "@/components/ui/overlays";
import { SidebarMenu, SidebarMenuButton, SidebarMenuItem, useSidebar } from "@/components/ui/sidebar";

/** The signed-in person at the bottom of the sidebar, with an account menu. */
export function NavUser({ user }: { user: { name: string; email: string } }) {
  const { isMobile, state } = useSidebar();
  return (
    <SidebarMenu>
      <SidebarMenuItem>
        <Menu
          label={`Account menu for ${user.name}`}
          className="flex w-full"
          placement={!isMobile && state === "collapsed" ? "right-end" : "top-start"}
          items={[
            { label: "Profile", icon: "user" },
            { label: "Billing", icon: "credit-card" },
            { label: "Notifications", icon: "bell" },
            { label: "Sign out", icon: "sign-out", separatorBefore: true },
          ]}
          trigger={({ ref, ...p }) => (
            <SidebarMenuButton ref={ref as React.Ref<HTMLElement>} {...p} size="lg" tooltip={user.name}>
              <Avatar name={user.name} decorative />
              <span className="flex min-w-0 flex-1 flex-col">
                <span className="truncate text-label-medium text-fg-primary">{user.name}</span>
                <span className="truncate text-caption-default">{user.email}</span>
              </span>
              <Icon name={ChevronsUpDown} size={16} />
            </SidebarMenuButton>
          )}
        />
      </SidebarMenuItem>
    </SidebarMenu>
  );
}

"use client";
import type { ReactNode } from "react";
import { Breadcrumbs } from "@/components/ui/nav-extra";
import { SidebarTrigger } from "@/components/ui/sidebar";

/** The bar above the page: sidebar toggle, breadcrumbs and optional actions on the end side. */
export function SiteHeader({ crumbs, actions }: { crumbs: { label: string; href?: string }[]; actions?: ReactNode }) {
  return (
    <header className="sticky top-0 z-[var(--ds-z-sticky)] flex h-14 shrink-0 items-center gap-2 border-b border-line-default bg-surface px-4 md:rounded-t-[inherit]">
      <SidebarTrigger className="-ms-1" />
      <span aria-hidden className="mx-1 h-4 w-px bg-line-default" />
      <Breadcrumbs items={crumbs} />
      {actions && <div className="ms-auto flex items-center gap-2">{actions}</div>}
    </header>
  );
}

"use client";
import { useMemo, useState } from "react";
import { Button } from "@/components/ui/button";
import { Table, type SortDir } from "@/components/ui/data";
import { Badge } from "@/components/ui/feedback";
import { Chip, SearchField } from "@/components/ui/form";
import { Pagination } from "@/components/ui/nav-extra";

type Status = "Backlog" | "Todo" | "In progress" | "Done";
type Task = { id: string; title: string; label: string; status: Status; priority: "Low" | "Medium" | "High"; assignee: string };
const titles = ["Fix login redirect", "Write onboarding emails", "Audit color contrast", "Migrate invoices table", "Add CSV export", "Field map: offline tiles", "Rename projects to spaces", "Reduce bundle size", "Dark mode for charts", "Translate settings to Filipino", "Keyboard shortcuts help", "Archive old reports"];
const statuses: Status[] = ["Backlog", "Todo", "In progress", "Done"];
const people = ["Jane Cooper", "Wade Warren", "Esther Howard", "Leo Santos"];
const tasks: Task[] = titles.map((t, i) => ({
  id: `TASK-${8710 + i * 7}`, title: t, label: ["Bug", "Feature", "Docs"][i % 3], status: statuses[(i * 3) % 4],
  priority: (["Low", "Medium", "High"] as const)[(i * 2) % 3], assignee: people[i % 4],
}));
const statusTone = { Backlog: "neutral", Todo: "info", "In progress": "brand", Done: "success" } as const;
const PAGE = 6;

export function TasksTable() {
  const [q, setQ] = useState("");
  const [filters, setFilters] = useState<Set<Status>>(new Set());
  const [sort, setSort] = useState<{ key: string; direction: SortDir } | null>(null);
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [page, setPage] = useState(1);

  const rows = useMemo(() => tasks.filter((t) => (!q || `${t.id} ${t.title}`.toLowerCase().includes(q.toLowerCase())) && (!filters.size || filters.has(t.status))), [q, filters]);
  const pageCount = Math.max(1, Math.ceil(rows.length / PAGE));
  const shown = rows.slice((page - 1) * PAGE, page * PAGE);
  const allOnPage = shown.length > 0 && shown.every((r) => selected.has(r.id));
  const toggle = (id: string) => setSelected((s) => { const n = new Set(s); if (n.has(id)) n.delete(id); else n.add(id); return n; });

  return (
    <div className="flex flex-col gap-3">
      <div className="flex flex-wrap items-center gap-2">
        <div className="w-full sm:w-64"><SearchField label="Search tasks" placeholder="Search tasks" size="sm" value={q} onChange={(v) => { setQ(v); setPage(1); }} onClear={() => setQ("")} /></div>
        <div role="group" aria-label="Filter by status" className="flex flex-wrap gap-2">
          {statuses.map((s) => (
            <Chip key={s} selected={filters.has(s)} onToggle={(on) => { setFilters((f) => { const n = new Set(f); if (on) n.add(s); else n.delete(s); return n; }); setPage(1); }}>{s}</Chip>
          ))}
        </div>
        {(q || filters.size > 0) && <Button variant="ghost" size="sm" onClick={() => { setQ(""); setFilters(new Set()); }}>Reset</Button>}
      </div>
      <div role="region" aria-label="Bulk actions" aria-live="polite" className={selected.size ? "flex flex-wrap items-center gap-2 rounded-container border border-line-default bg-selected px-4 py-2" : "sr-only"}>
        {selected.size > 0 && (
          <>
            <span className="text-label-medium">{selected.size} selected</span>
            <Button size="sm" variant="secondary" leadingIcon="check">Mark done</Button>
            <Button size="sm" variant="secondary" leadingIcon="user">Assign</Button>
            <Button size="sm" variant="ghost" tone="danger" leadingIcon="trash">Delete</Button>
            <Button size="sm" variant="ghost" className="ms-auto" onClick={() => setSelected(new Set())}>Clear selection</Button>
          </>
        )}
      </div>
      <Table<Task>
        caption="Tasks"
        captionHidden
        rows={shown}
        rowKey={(t) => t.id}
        sort={sort}
        onSortChange={setSort}
        empty={<p className="py-6 text-center text-body-small text-fg-secondary">No tasks match. Try another word or clear the filters.</p>}
        columns={[
          {
            key: "select", header: "Select", headerHidden: true, width: 48,
            render: (t) => <input type="checkbox" aria-label={`Select ${t.id}`} checked={selected.has(t.id)} onChange={() => toggle(t.id)} className="size-4 accent-[var(--ds-color-bg-brand)] focus-visible:focus-ring" />,
          },
          { key: "id", header: "Task", sortable: true, width: 120, render: (t) => <span className="font-mono text-code-small">{t.id}</span> },
          { key: "title", header: "Title", sortable: true, render: (t) => <span className="flex items-center gap-2"><Badge>{t.label}</Badge><span className="truncate">{t.title}</span></span> },
          { key: "status", header: "Status", sortable: true, sortValue: (t) => statuses.indexOf(t.status), render: (t) => <Badge tone={statusTone[t.status]}>{t.status}</Badge> },
          { key: "priority", header: "Priority", sortable: true, sortValue: (t) => ["Low", "Medium", "High"].indexOf(t.priority) },
          { key: "assignee", header: "Assignee" },
        ]}
      />
      <div className="flex flex-wrap items-center gap-3">
        <label className="flex items-center gap-2 text-body-small">
          <input type="checkbox" checked={allOnPage} onChange={() => setSelected((s) => { const n = new Set(s); shown.forEach((r) => (allOnPage ? n.delete(r.id) : n.add(r.id))); return n; })} className="size-4 accent-[var(--ds-color-bg-brand)] focus-visible:focus-ring" />
          Select all on this page
        </label>
        <div className="ms-auto"><Pagination page={page} pageCount={pageCount} onPageChange={setPage} summary={`${rows.length} tasks`} /></div>
      </div>
    </div>
  );
}
